(()=>{'use strict';const $=s=>document.querySelector(s);let client,questions=[];const cfg=window.BUTTON_CONFIG||{};const score=p=>Math.max(0,Math.round(100-2*Math.abs(p-50)));function quality(s){return s>=90?['EXCELLENT','good']:s>=80?['STRONG','good']:s>=70?['USABLE','']:s>=50?['NEEDS REVISION','warn']:['TOO ONE-SIDED','bad']}function setup(){if(!cfg.SUPABASE_URL||!cfg.SUPABASE_ANON_KEY||!window.supabase){$('#loginStatus').textContent='Connect Supabase in config.js to enable the secure dashboard.';return}client=window.supabase.createClient(cfg.SUPABASE_URL,cfg.SUPABASE_ANON_KEY);client.auth.getSession().then(({data})=>auth(data.session));client.auth.onAuthStateChange((_,session)=>auth(session))}async function auth(session){if(!session){$('#login').hidden=false;$('#dashboard').hidden=true;$('#signOut').hidden=true;return}$('#login').hidden=true;$('#dashboard').hidden=false;$('#signOut').hidden=false;await load()}$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginStatus').textContent='Sending secure link…';const{error}=await client.auth.signInWithOtp({email:$('#email').value,options:{emailRedirectTo:location.href}});$('#loginStatus').textContent=error?'Sign-in failed. Check that this email is an approved admin.':'Check your inbox for the secure sign-in link.'};$('#signOut').onclick=()=>client.auth.signOut();async function load(){const{data,error}=await client.from('question_admin_stats').select('*');if(error){console.error(error);return}questions=data||[];const cats=[...new Set(questions.map(q=>q.category))].sort();$('#categoryFilter').innerHTML='<option value="">All categories</option>'+cats.map(c=>`<option>${escapeHtml(c)}</option>`).join('');render()}function render(){const cat=$('#categoryFilter').value,q=$('#search').value.toLowerCase(),sort=$('#sortBy').value;let rows=questions.filter(x=>(!cat||x.category===cat)&&(!q||(x.benefit_text+' '+x.consequence_text).toLowerCase().includes(q)));rows.sort((a,b)=>sort==='votes'?b.total_votes-a.total_votes:sort==='newest'?new Date(b.created_at)-new Date(a.created_at):sort==='one-sided'?score(a.press_percentage)-score(b.press_percentage):score(b.press_percentage)-score(a.press_percentage));$('#mActive').textContent=questions.filter(x=>x.active).length;$('#mVotes').textContent=questions.reduce((n,x)=>n+Number(x.total_votes),0).toLocaleString();$('#mStrong').textContent=questions.filter(x=>score(x.press_percentage)>=80).length;$('#mRevision').textContent=questions.filter(x=>x.total_votes>0&&score(x.press_percentage)<70).length;$('#questionRows').innerHTML=rows.map(x=>{const s=score(x.press_percentage),qual=quality(s);return`<tr><td>#${x.id}</td><td class="dilemma"><strong>${escapeHtml(x.benefit_text)}</strong><span>But ${escapeHtml(x.consequence_text)}</span></td><td><div class="result-mini"><b><span>${Math.round(x.press_percentage)}% press</span><span>${100-Math.round(x.press_percentage)}%</span></b><div class="mini-bar"><span style="width:${x.press_percentage}%"></span></div></div></td><td>${Number(x.total_votes).toLocaleString()}</td><td><span class="badge ${qual[1]}">${s} · ${qual[0]}</span></td><td><button class="toggle ${x.active?'':'off'}" data-toggle="${x.id}">${x.active?'ACTIVE':'INACTIVE'}</button></td><td><button class="edit" data-edit="${x.id}">EDIT</button></td></tr>`}).join('');$('#empty').hidden=!!rows.length;document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>toggle(Number(b.dataset.toggle)));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(Number(b.dataset.edit)))}function escapeHtml(s=''){return s.replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}async function toggle(id){const q=questions.find(x=>x.id===id);const{error}=await client.from('questions').update({active:!q.active}).eq('id',id);if(!error){q.active=!q.active;render()}}function openEditor(id){const q=questions.find(x=>x.id===id);$('#questionId').value=q?.id||'';$('#editorTitle').textContent=q?'Edit question':'Add question';$('#editCategory').value=q?.category||'';$('#editBenefit').value=q?.benefit_text||'';$('#editConsequence').value=q?.consequence_text||'';$('#editPressValue').value=q?.press_value||'';$('#editWalkValue').value=q?.walk_value||'';$('#editActive').checked=q?.active??true;$('#editorStatus').textContent='';$('#editor').showModal()}$('#addQuestion').onclick=()=>openEditor();$('#closeEditor').onclick=()=>$('#editor').close();$('#editorForm').onsubmit=async e=>{e.preventDefault();const id=$('#questionId').value,payload={category:$('#editCategory').value.trim(),benefit_text:$('#editBenefit').value.trim(),consequence_text:$('#editConsequence').value.trim(),press_value:$('#editPressValue').value.trim(),walk_value:$('#editWalkValue').value.trim(),active:$('#editActive').checked};$('#editorStatus').textContent='Saving…';const result=id?await client.from('questions').update(payload).eq('id',id):await client.from('questions').insert(payload);if(result.error){$('#editorStatus').textContent='Could not save this question.';console.error(result.error)}else{$('#editor').close();await load()}};['#categoryFilter','#sortBy'].forEach(s=>$(s).onchange=render);$('#search').oninput=render;setup()})();
